:root{--bg:#07111e;--panel:#0d1828;--panel2:#112238;--line:#233a56;--text:#f6fbff;--muted:#8fa8c5;--accent:#16c7ff;--accent2:#2f63ff;--ok:#42e0a0;--warn:#ffbd59;--danger:#ff6f7d;--glow:0 0 30px rgba(22,199,255,.22)}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 18% -10%,#0e3d74 0,transparent 32%),linear-gradient(180deg,#06101c,#0a1320 55%,#08111d);color:var(--text);font-family:Inter,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;height:100vh;overflow:hidden}button,textarea{font:inherit}a{text-decoration:none;color:inherit}.app{height:100vh;display:grid;grid-template-rows:auto 1fr}.top{display:flex;align-items:center;justify-content:space-between;gap:14px;min-height:86px;padding:10px 16px;border-bottom:1px solid var(--line);background:rgba(5,13,23,.92);backdrop-filter:blur(16px);min-width:0}.brand{display:flex;align-items:center;gap:14px;min-width:0;flex:0 0 auto}.brand-logo{width:78px;height:58px;object-fit:cover;border-radius:14px;box-shadow:var(--glow);border:1px solid #1d5474}.brand h1{font-size:20px;margin:0}.brand small{color:var(--muted)}.actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap;justify-content:flex-end;min-width:0;max-width:calc(100vw - 390px)}.btn{border:1px solid var(--line);color:var(--text);background:#101d2f;border-radius:11px;padding:9px 12px;cursor:pointer;font-weight:780;transition:.18s;white-space:nowrap;flex:0 0 auto}.btn:hover{border-color:#3d6f9a;transform:translateY(-1px)}.btn.primary{background:linear-gradient(135deg,#1d8dff,#2f63ff);border-color:#4e87ff;box-shadow:0 0 22px rgba(47,99,255,.22)}.btn.ok{background:#123728;border-color:#26614a;color:#9df2c8}.btn.build{background:linear-gradient(135deg,#0a5a89,#19396f);border-color:#287fb0}.build-pill{padding:8px 10px;border-radius:999px;border:1px solid var(--line);background:#0f1a2a;color:var(--muted);font-size:12px;font-weight:800;white-space:nowrap;flex:0 1 auto;max-width:210px;overflow:hidden;text-overflow:ellipsis}.build-pill.busy{color:#ffe0a0;border-color:#735a2b;background:#2a2112}.build-pill.success{color:#9df2c8;border-color:#2f6d50;background:#123728}.build-pill.fail{color:#ffc4cb;border-color:#6b343d;background:#2d1519}.layout{display:grid;grid-template-columns:240px 340px 1fr;min-height:0}.sidebar,.files{border-right:1px solid var(--line);background:rgba(9,18,31,.95);overflow:auto}.sidebar{padding:18px 13px}.section-label{font-size:11px;text-transform:uppercase;letter-spacing:.14em;color:#6f8aaa;margin:4px 10px 10px}.project{width:100%;border:1px solid transparent;background:transparent;color:var(--text);border-radius:12px;padding:12px;text-align:left;cursor:pointer;display:flex;align-items:center;gap:10px;margin-bottom:6px}.project:hover,.project.active{background:#12233a;border-color:#2b4f70}.ico{width:36px;height:36px;border-radius:10px;background:linear-gradient(135deg,#112945,#0b5a7d);display:grid;place-items:center}.download-panel{margin-top:22px;padding:14px 10px;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.download-title{font-size:11px;text-transform:uppercase;letter-spacing:.14em;color:#6f8aaa;margin-bottom:8px}.download-version{font-weight:900;color:#dff7ff;margin-bottom:9px}.download-link{display:block;padding:9px 10px;margin-top:7px;border:1px solid #28614c;border-radius:10px;background:#123728;color:#9df2c8;font-weight:800;font-size:12px;text-align:center}.download-link:hover{border-color:#3e8e6d;background:#164532}.download-link[aria-disabled="true"]{opacity:.5;pointer-events:none}.download-note{margin-top:8px;color:#6f8aaa;font-size:10px;line-height:1.4}.sidebar-footer{margin-top:18px;padding:12px;border-top:0;color:var(--muted);font-size:12px}.files{padding:15px}.crumb{display:flex;gap:7px;align-items:center;min-height:36px;color:var(--muted);font-size:13px;margin-bottom:8px}.file-row{display:flex;align-items:center;gap:9px;padding:9px;border-radius:9px;cursor:pointer;color:#dbe7f5}.file-row:hover{background:#13253b}.file-row.folder{color:#e6d08b}.file-name{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.file-size{margin-left:auto;color:#607c9b;font-size:11px}.editor{min-width:0;display:grid;grid-template-rows:52px 1fr 32px;background:#07111d}.editor-head{display:flex;align-items:center;gap:10px;padding:0 16px;border-bottom:1px solid var(--line);background:#0c1727}.path{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:#bed0e4;font-size:13px}.dirty{display:none;width:8px;height:8px;border-radius:50%;background:var(--warn)}textarea{width:100%;height:100%;resize:none;border:0;outline:0;padding:18px 20px;background:#07111d;color:#dce8f7;font:14px/1.55 "SFMono-Regular",Consolas,"Liberation Mono",monospace;tab-size:4}.empty{display:grid;place-items:center;color:#667d98}.statusbar{display:flex;align-items:center;justify-content:space-between;padding:0 12px;border-top:1px solid var(--line);color:#6e86a3;font-size:11px;background:#0a1523}.git-state{display:flex;align-items:center;gap:7px}.dot{width:8px;height:8px;border-radius:50%;background:var(--ok)}.toast{position:fixed;right:20px;bottom:20px;min-width:270px;max-width:460px;background:#102036;border:1px solid #34577e;border-radius:12px;padding:13px 15px;box-shadow:0 20px 60px #0009;display:none;z-index:50}.toast.error{border-color:#6b3439;color:#ffc4c8}.commit{color:#98b1ce;font-size:12px;flex:1 1 150px;min-width:100px;max-width:280px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}@media(max-width:1280px){.commit{display:none}.actions{max-width:calc(100vw - 370px)}}@media(max-width:1050px){.layout{grid-template-columns:210px 290px 1fr}.top{align-items:flex-start}.actions{max-width:calc(100vw - 335px)}.brand-logo{width:68px;height:52px}.brand h1{font-size:18px}.btn{padding:8px 10px}.build-pill{max-width:170px}}@media(max-width:820px){body{overflow:auto}.app{height:auto}.top{padding:12px;align-items:flex-start;flex-direction:column}.brand-logo{width:66px;height:50px}.actions{justify-content:flex-start;max-width:none;width:100%}.layout{display:block}.sidebar,.files{max-height:340px;border-right:0;border-bottom:1px solid var(--line)}.editor{height:70vh}}
</style>
