<section class="editor"><div class="editor-head"><span class="dirty" id="dirty"></span><span class="path" id="openPath">Geen bestand geopend</span></div><div id="editorWrap" class="empty">Kies links een bestand om te bewerken.</div><div class="statusbar"><span id="fileMeta">—</span><span>UTF-8 • Auto-sync actief</span></div></section>
</div>
</div>
<div class="toast" id="toast"></div>
<script>
const CSRF=<?php echo json_encode($csrf,JSON_UNESCAPED_SLASHES);?>;
let state={project:'app',dir:'',file:'',original:'',dirty:false};
let autoPollTimer=null,lastReleaseTag='';
const $=s=>document.querySelector(s);
function toast(msg,error=false){const t=$('#toast');t.textContent=msg;t.className='toast'+(error?' error':'');t.style.display='block';clearTimeout(window.__tt);window.__tt=setTimeout(()=>t.style.display='none',3500)}
async function api(action,opts={}){const method=opts.method||'GET';let url='api.php?action='+encodeURIComponent(action);if(opts.params)url+='&'+new URLSearchParams(opts.params);const init={method,headers:{Accept:'application/json'},cache:'no-store'};if(method!=='GET'){init.headers['Content-Type']='application/json';init.headers['X-CSRF-Token']=CSRF;init.body=JSON.stringify(opts.body||{})}const r=await fetch(url,init);const j=await r.json().catch(()=>({ok:false,error:'Ongeldige serverreactie'}));if(!r.ok||j.ok===false)throw new Error(j.error||('HTTP '+r.status));return j}
function humanSize(n){if(n==null)return'';if(n<1024)return n+' B';if(n<1048576)return(n/1024).toFixed(1)+' KB';return(n/1048576).toFixed(1)+' MB'}
async function loadStatus(){try{const j=await api('status');$('#branch').textContent=j.data.branch||'main';$('#latestCommit').textContent=j.data.commit||'';const clean=!j.data.status;$('#repoStatus').textContent=clean?'Working tree clean':'Wijzigingen aanwezig';$('#gitDot').style.background=clean?'var(--ok)':'var(--warn)'}catch(e){$('#repoStatus').textContent='Status fout';$('#gitDot').style.background='var(--danger)'}}
async function loadBuildStatus(){const pill=$('#buildPill');try{const r=await fetch('https://api.github.com/repos/Rubenvaggelen/apps/actions/workflows/build-apk.yml/runs?branch=main&per_page=1',{headers:{Accept:'application/vnd.github+json'},cache:'no-store'});if(!r.ok)throw new Error('HTTP '+r.status);const j=await r.json();const run=j.workflow_runs&&j.workflow_runs[0];if(!run){pill.textContent='Geen builds';pill.className='build-pill';return{busy:false,success:false}}const busy=run.status==='queued'||run.status==='in_progress';if(busy){pill.textContent='Build bezig • #'+run.run_number;pill.className='build-pill busy'}else if(run.conclusion==='success'){pill.textContent='Build geslaagd • v'+run.run_number;pill.className='build-pill success'}else{pill.textContent='Build '+(run.conclusion||'mislukt')+' • #'+run.run_number;pill.className='build-pill fail'}return{busy,success:run.conclusion==='success',number:run.run_number}}catch(e){pill.textContent='Buildstatus onbekend';pill.className='build-pill';return null}}
async function loadLatestRelease(){const version=$('#releaseVersion'),app=$('#appDownload'),car=$('#carDownload'),note=$('#releaseNote');app.removeAttribute('href');car.removeAttribute('href');app.setAttribute('aria-disabled','true');car.setAttribute('aria-disabled','true');try{const r=await fetch('https://api.github.com/repos/Rubenvaggelen/apps/releases/latest',{headers:{Accept:'application/vnd.github+json'},cache:'no-store'});if(!r.ok)throw new Error('HTTP '+r.status);const rel=await r.json();const tag=rel.tag_name||'Laatste release';version.textContent=tag;const assets=Array.isArray(rel.assets)?rel.assets:[];const appAsset=assets.find(a=>a.name==='app-debug.apk');const carAsset=assets.find(a=>a.name==='carradio-debug.apk');if(appAsset){app.href=appAsset.browser_download_url;app.removeAttribute('aria-disabled')}if(carAsset){car.href=carAsset.browser_download_url;car.removeAttribute('aria-disabled')}note.textContent=appAsset&&carAsset?'Klaar om direct te downloaden. Auto-sync actief.':'Niet alle APK-bestanden zijn beschikbaar in deze release.';if(lastReleaseTag&&lastReleaseTag!==tag)toast('Nieuwe APK-release '+tag+' is klaar.');lastReleaseTag=tag;return tag}catch(e){version.textContent='Release onbekend';note.textContent='Kon de nieuwste release niet laden. Gebruik Builds als alternatief.';return null}}
function scheduleAutoRefresh(ms){clearTimeout(autoPollTimer);autoPollTimer=setTimeout(autoRefreshHub,ms)}
async function autoRefreshHub(){if(document.hidden){scheduleAutoRefresh(180000);return}const build=await loadBuildStatus();await loadStatus();if(build&&build.success)await loadLatestRelease();scheduleAutoRefresh(build&&build.busy?15000:180000)}
async function listFiles(){try{const j=await api('list',{params:{project:state.project,path:state.dir}});$('#crumb').textContent=state.project+' / '+(state.dir?state.dir+'/':'');$('#fileList').innerHTML='';j.data.items.sort((a,b)=>(a.type===b.type?a.name.localeCompare(b.name):a.type==='folder'?-1:1)).forEach(it=>{const row=document.createElement('div');row.className='file-row '+(it.type==='folder'?'folder':'');row.innerHTML=`<span>${it.type==='folder'?'📁':'📄'}</span><span class="file-name"></span><span class="file-size">${humanSize(it.size)}</span>`;row.querySelector('.file-name').textContent=it.name;row.onclick=()=>it.type==='folder'?openDir(it.name):openFile(it.name);$('#fileList').appendChild(row)})}catch(e){toast(e.message,true)}}
function openDir(name){state.dir=state.dir?state.dir+'/'+name:name;listFiles()}
function up(){if(!state.dir)return;state.dir=state.dir.split('/').slice(0,-1).join('/');listFiles()}
async function openFile(name){if(state.dirty&&!confirm('Niet-opgeslagen wijzigingen weggooien?'))return;const path=state.dir?state.dir+'/'+name:name;try{const j=await api('read',{params:{project:state.project,path}});state.file=path;state.original=j.data.content;state.dirty=false;$('#dirty').style.display='none';$('#saveBtn').disabled=false;$('#openPath').textContent=state.project+'/'+path;const ta=document.createElement('textarea');ta.value=j.data.content;ta.spellcheck=false;ta.oninput=()=>{state.dirty=ta.value!==state.original;$('#dirty').style.display=state.dirty?'inline-block':'none'};$('#editorWrap').className='';$('#editorWrap').innerHTML='';$('#editorWrap').appendChild(ta);$('#fileMeta').textContent=humanSize(new Blob([j.data.content]).size)}catch(e){toast(e.message,true)}}
async function saveFile(){const ta=$('#editorWrap textarea');if(!ta||!state.file)return;try{await api('save',{method:'POST',body:{project:state.project,path:state.file,content:ta.value}});state.original=ta.value;state.dirty=false;$('#dirty').style.display='none';toast('Bestand opgeslagen');loadStatus()}catch(e){toast(e.message,true)}}
async function pull(){try{const j=await api('pull',{method:'POST'});toast(j.data.output||'Pull voltooid');loadStatus();listFiles()}catch(e){toast(e.message,true)}}
async function commitPush(){if(state.dirty){toast('Sla het geopende bestand eerst op.',true);return}const message=prompt('Commit message:','Update via The One Dev Hub');if(!message)return;try{const j=await api('commitpush',{method:'POST',body:{message}});toast(j.data.output||'Commit & push voltooid');loadStatus();clearTimeout(autoPollTimer);setTimeout(autoRefreshHub,1500)}catch(e){toast(e.message,true)}}
function switchProject(project){if(state.dirty&&!confirm('Niet-opgeslagen wijzigingen weggooien?'))return;state={project,dir:'',file:'',original:'',dirty:false};document.querySelectorAll('.project').forEach(b=>b.classList.toggle('active',b.dataset.project===project));$('#editorWrap').className='empty';$('#editorWrap').textContent='Kies links een bestand om te bewerken.';$('#openPath').textContent='Geen bestand geopend';$('#saveBtn').disabled=true;$('#dirty').style.display='none';listFiles()}
document.querySelectorAll('.project').forEach(b=>b.onclick=()=>switchProject(b.dataset.project));$('#upBtn').onclick=up;$('#saveBtn').onclick=saveFile;$('#pullBtn').onclick=pull;$('#pushBtn').onclick=commitPush;window.addEventListener('beforeunload',e=>{if(state.dirty){e.preventDefault();e.returnValue=''}});document.addEventListener('visibilitychange',()=>{if(!document.hidden){clearTimeout(autoPollTimer);autoRefreshHub()}});loadLatestRelease();listFiles();autoRefreshHub();
</script>
</body>
</html>
